6	public final class Dinheiro {
7	    public static final BigDecimal ZERO = arredondar(BigDecimal.ZERO);
8	
9	    private Dinheiro() {
10	    }
11	
12	    /** Arredonda para centavos, meio para o par. */
13	    public static BigDecimal arredondar(BigDecimal valor) {
14	        return valor.setScale(2, RoundingMode.HALF_EVEN);
15	    }
16	
17	    public static BigDecimal percentual(BigDecimal base, BigDecimal fracao) {
18	        return arredondar(base.multiply(fracao));
19	    }
20	}
