1	package loja.checkout.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	import org.springframework.stereotype.Component;
8	
9	import loja.checkout.Dinheiro;
10	
11	@Component
12	public class Cartao implements FormaPagamento {
13	    private static final int MAXIMO_PARCELAS = 12;
14	    private static final int MAXIMO_SEM_JUROS = 3;
15	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
16	
17	    @Override
18	    public String codigo() {
19	        return "CARTAO";
20	    }
21	
22	    @Override
23	    public boolean aceitaParcelas(int parcelas) {
24	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
25	    }
26	
27	    @Override
28	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
29	        BigDecimal parcela = parcelas <= MAXIMO_SEM_JUROS
30	                ? Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128))
31	                : parcelaPrice(totalPedido, parcelas);
32	        BigDecimal total = parcelas <= MAXIMO_SEM_JUROS ? totalPedido : parcela.multiply(BigDecimal.valueOf(parcelas));
33	        return new Cobranca(total, parcela);
34	    }
35	
36	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
37	    private BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
38	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
39	        BigDecimal descontado = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
40	        return total.multiply(TAXA_MENSAL).divide(descontado, MathContext.DECIMAL128)
41	                .setScale(2, RoundingMode.HALF_EVEN);
42	    }
43	}
